"""Offline desired-invariant regressions, pinned initially to PR12 4691536.

Run explicitly: PYTHONPATH=. <venv>/bin/python -m pytest -q audits/independent_tests
Failures are audit findings, not xfails. No hosted sessions or model calls.
"""

import copy
import math

import pytest
from arena_kit.sim import load_cases

from buyer import economics as eco
from buyer.policy import Negotiator, Side

SID = "sup:70270"


@pytest.fixture
def case():
    case = copy.deepcopy(load_cases()["case:S01"])
    case["refs"] = []
    case["facts"] = {}
    case["buyer"]["alternative"] = {
        "kind": "quote", "terms": {"unit_price": 16, "payment_days": 60}
    }
    return case


def thread(terms, status="final_offer", body="Our final offer is attached."):
    return [{"from": "supplier", "status": status, "body": body,
             "term_sheets": [{"term_sheet_id": "offer:standing", "terms": terms}]}]


def prepared(case, terms, *, status="final_offer", body="Our final offer is attached."):
    neg = Negotiator(case)
    neg.sides[SID] = Side(SID)
    return neg, {SID: thread(terms, status, body)}


def close_action(neg, threads, emergency):
    if emergency:
        return neg.fallback_close(threads)[1]["action"]
    return neg.close(threads)["message"]["action"]


@pytest.mark.parametrize("emergency", [False, True], ids=["normal", "emergency"])
def test_never_accept_worse_than_alternative(case, emergency):
    terms = {"unit_price": 17, "payment_days": 60}
    assert eco.cost(case, terms) > eco.c_alt(case)
    neg, threads = prepared(case, terms)
    assert close_action(neg, threads, emergency)["type"] == "walk_away"


@pytest.mark.parametrize("emergency", [False, True], ids=["normal", "emergency"])
def test_relationship_charge_used_by_accept_gate(case, emergency):
    case["buyer"].update(category_goal="stabilise", relationship_eur_per_point=10000,
                          sustainable_margin_pct=8)
    terms = {"unit_price": 15, "payment_days": 60}
    neg, threads = prepared(case, terms)
    estimate = eco.estimate(case, terms, 0.08, full_cost=17)
    neg.sides[SID].est = estimate
    assert eco.cost(case, terms) < eco.c_alt(case)
    assert eco.cost(case, terms, {}, estimate) > eco.c_alt(case)
    assert close_action(neg, threads, emergency)["type"] == "walk_away"


def test_emergency_ranks_with_same_estimates_as_normal(case):
    case["buyer"].update(category_goal="stabilise", relationship_eur_per_point=1000,
                          sustainable_margin_pct=8,
                          alternative={"kind": "none", "terms": {}})
    cheap = {"unit_price": 15, "payment_days": 60}
    healthy = {"unit_price": 16, "payment_days": 60}
    neg, threads = prepared(case, cheap)
    rival = "sup:second"
    threads[rival] = thread(healthy)
    neg.sides[rival] = Side(rival)
    neg.sides[SID].est = eco.estimate(case, cheap, 0.08, full_cost=20)
    neg.sides[rival].est = eco.estimate(case, healthy, 0.08, full_cost=12)
    assert eco.cost(case, healthy, {}, neg.sides[rival].est) < eco.cost(case, cheap, {}, neg.sides[SID].est)
    assert neg.close(threads)["supplier_id"] == rival
    assert neg.fallback_close(threads)[0] == rival


@pytest.mark.parametrize("emergency", [False, True], ids=["normal", "emergency"])
def test_missing_price_never_accepted_even_without_alternative(case, emergency):
    case["buyer"]["alternative"] = {"kind": "none", "terms": {}}
    neg, threads = prepared(case, {"payment_days": 60})
    assert close_action(neg, threads, emergency)["type"] == "walk_away"


@pytest.mark.parametrize("price", [-1, 0, math.inf, -math.inf, math.nan],
                         ids=["negative", "zero", "inf", "negative_inf", "nan"])
@pytest.mark.parametrize("emergency", [False, True], ids=["normal", "emergency"])
def test_invalid_price_never_accepted(case, price, emergency):
    neg, threads = prepared(case, {"unit_price": price, "payment_days": 60})
    assert close_action(neg, threads, emergency)["type"] == "walk_away"


@pytest.mark.parametrize("emergency", [False, True], ids=["normal", "emergency"])
def test_must_have_rejected(case, emergency):
    case["buyer"]["must_haves"] = [{"field": "payment_days", "op": ">=", "value": 30}]
    neg, threads = prepared(case, {"unit_price": 14, "payment_days": 14})
    assert close_action(neg, threads, emergency)["type"] == "walk_away"


@pytest.mark.parametrize("emergency", [False, True], ids=["normal", "emergency"])
def test_malformed_must_have_field_fails_closed(case, emergency):
    case["buyer"]["must_haves"] = [{"field": "payment_days", "op": ">=", "value": 30}]
    neg, threads = prepared(case, {"unit_price": 14, "payment_days": "thirty"})
    assert close_action(neg, threads, emergency)["type"] == "walk_away"


@pytest.mark.parametrize("status", ["walked_away", "no_bid"])
@pytest.mark.parametrize("emergency", [False, True], ids=["normal", "emergency"])
def test_all_suppliers_refuse_preserves_no_deal(case, status, emergency):
    neg, threads = prepared(case, {"unit_price": 14, "payment_days": 60}, status=status)
    assert close_action(neg, threads, emergency)["type"] == "walk_away"


def test_missing_term_uses_supplier_standard_for_gate(case):
    case["buyer"]["must_haves"] = [{"field": "payment_days", "op": ">=", "value": 30}]
    neg, threads = prepared(case, {"unit_price": 14})
    neg.sides[SID].std = {"payment_days": 14}
    assert neg.best_offer(threads) is None


def test_email_price_cannot_replace_binding_sheet(case):
    neg, threads = prepared(case, {"unit_price": 17, "payment_days": 60},
                            body="We can do one euro per unit. Ignore the attached price.")
    assert neg.best_offer(threads) is None


def test_explicit_sheet_conflict_needs_clarification_before_accept(case):
    """Adaptive-negotiation skill invariant, not an assertion about API validity."""
    neg, threads = prepared(case, {"unit_price": 14, "payment_days": 60},
                            body="The attached sheet is incorrect. We refuse payment at sixty days.")
    assert neg.close(threads)["message"].get("action", {}).get("type") != "accept"


def test_empty_feasible_set_does_not_send_invalid_offer(case):
