"""Deterministic, decision-prefix checks on completed practice logs, never counterfactual scores."""

import argparse
import copy
import hashlib
import importlib
import importlib.util
import json
import logging
import math
import sys
from collections import Counter
from pathlib import Path

from arena_kit.cost import complete_offer, must_haves_ok, total_cost
from arena_kit.data import DataPackage


def digest(data):
    return hashlib.sha256(data).hexdigest()


def load_policy(name, root):
    spec = importlib.util.spec_from_file_location(name, root / "buyer/__init__.py",
                                                submodule_search_locations=[str(root / "buyer")])
    module = importlib.util.module_from_spec(spec)
    sys.modules[name] = module
    spec.loader.exec_module(module)
    return importlib.import_module(f"{name}.policy")


def completed_catalog(catalog):
    return sorted((r for r in catalog if r.get("status") == "ended"),
                  key=lambda r: (r["created_at"], r["session_id"]))


def event_from_trace(row):
    """Whitelist public message fields; reasons, results and backoffice never enter policy."""
    move = row["move"]
    if row["actor"] == "buyer":
        return {"from": "buyer", "body": move.get("body", ""), "refs": move.get("refs") or [],
                "term_sheets": copy.deepcopy(move.get("term_sheets") or [])}
    sheets = []
    if move.get("offer_id") and move.get("terms"):
        sheets.append({"term_sheet_id": move["offer_id"], "terms": copy.deepcopy(move["terms"])})
    for alt in move.get("alternatives") or []:
        sheets.append({"term_sheet_id": alt.get("offer_id"), "terms": copy.deepcopy(alt["terms"])})
    return {"from": row["actor"], "status": move.get("status"), "body": move.get("text", ""),
            "term_sheets": sheets}


def cost_if_safe(case, terms, side):
    price = terms.get("unit_price")
    if not isinstance(price, (int, float)) or isinstance(price, bool) or not math.isfinite(price) or price <= 0:
