    try:
        if not must_haves_ok(case, terms, side.std):
            return None
        estimate = side.est if side.est.get("full_cost") else None
        cost = total_cost(case, terms, side.std, estimate)
        alt = case["buyer"].get("alternative") or {}
        alt_c = total_cost(case, alt["terms"]) if alt.get("terms", {}).get("unit_price") else math.inf
