    parser.add_argument("--candidate", type=Path, required=True)
    parser.add_argument("--data", type=Path)
    parser.add_argument("--out", type=Path, required=True)
    args = parser.parse_args()
    logging.basicConfig(level=logging.CRITICAL)
    catalog_bytes = (args.snapshot / "practice-catalog.json").read_bytes()
    catalog = completed_catalog(json.loads(catalog_bytes))
    case_bytes = (args.snapshot / "practice-cases.json").read_bytes()
    cases = {c["case_id"]: c for c in json.loads(case_bytes)}
    files = {json.loads(p.read_bytes())["session_id"]: p for p in (args.snapshot / "sessions/practice").glob("*.json")}
    # Read all selected bytes before executing a policy, freezing this snapshot in memory.
    frozen = {r["session_id"]: files[r["session_id"]].read_bytes() for r in catalog}
    latest = [r["session_id"] for r in catalog[-10:]]
    pkg = DataPackage(args.data) if args.data else None
    if pkg:
        pkg.lookup("")
    manifest = {"catalog_sha256": digest(catalog_bytes), "cases_sha256": digest(case_bytes),
                "sessions_sha256": {sid: digest(data) for sid, data in frozen.items()},
                "latest_ten": [{k: r[k] for k in ("session_id", "case_id", "created_at")} for r in catalog[-10:]],
                "policy_files": {label: {p.name: digest(p.read_bytes()) for p in sorted((path / "buyer").glob("*.py"))}
                                 for label, path in (("baseline", args.baseline), ("candidate", args.candidate))},
                "data_facts_sha256": digest(json.dumps(pkg.facts, sort_keys=True).encode()) if pkg else None}
    outputs = {}
    for label, path in (("baseline", args.baseline), ("candidate", args.candidate)):
        policy = load_policy(f"prefix_{label}", path)
        sessions = [replay_session(json.loads(data), cases[json.loads(data)["case_id"]], policy, pkg)
                    for data in frozen.values()]
        prefixes = [r for s in sessions for r in s["prefixes"]]
        latest_prefixes = [r for s in sessions if s["session_id"] in latest for r in s["prefixes"]]
        outputs[label] = {"summary": {"sessions": len(sessions), "reply_prefixes": len(prefixes),
                          "checks": sum(r["checks"] for r in prefixes),
                          "failed_prefixes": sum(bool(r["failures"]) for r in prefixes),
                          "failures": dict(Counter(f for r in prefixes for f in r["failures"])),
                          "terminal_prefixes": sum(r["status"] in ("agreed", "final_offer") for r in prefixes),
                          "unresolved_claim_refs": sum(len(r["unresolved_claim_refs"]) for r in prefixes),
                          "latest_ten_prefixes": len(latest_prefixes),
                          "latest_ten_failed_prefixes": sum(bool(r["failures"]) for r in latest_prefixes)},
                          "sessions": sessions}
    report = {"manifest": manifest, "variants": outputs, "limitations": [
        "Predictions are never fed into later historical replies: these are prefix regressions, not counterfactual scores.",
        "Policies receive only public case data and whitelisted messages up to the current reply; no result costs, scores or backoffice.",
        "The frozen published case/data snapshot may differ from data available at an older session's original execution.",
        "Historical quote-PDF attachment text is unavailable here; unspecified standards use kit defaults/opening terms.",
        "Relationship costs use policy estimates, not hidden supplier economics; costs are not exact hosted certifications.",
        "Claim checks establish reference existence and past-offer provenance, not numeric truth or persuasive effect.",
        "Restore reconstructs state from historical buyer messages; internal original policy state is unavailable.",
        "No hosted sessions, network or model calls. Latest ten means latest ten completed sessions, not latest one per case.",
    ]}
    args.out.mkdir(parents=True, exist_ok=True)
    (args.out / "report.json").write_text(json.dumps(report, indent=2, sort_keys=True) + "\n")
    print(json.dumps({k: v["summary"] for k, v in outputs.items()}, indent=2))
    print(json.dumps({"latest_ten": manifest["latest_ten"]}))


